### 4.6 Search.svelte — 搜索组件

[Search.svelte](file:///e:/GithubProgect/dumplingandcakeblog/src/components/controls/Search.svelte) 基于 Pagefind 实现全文搜索：

```svelte
<script lang="ts">
import { onMount } from "svelte";

let keywordDesktop = "";
let keywordMobile = "";
let result: SearchResult[] = [];
let isSearching = false;
let initialized = false;

// 300ms 防抖搜索
const search = async (keyword: string, isDesktop: boolean): Promise<void> => {
  if (!keyword) { setPanelVisibility(false, isDesktop); return; }
  if (!initialized) return;

  isSearching = true;
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(async () => {
    try {
      let searchResults: SearchResult[] = [];
      if (import.meta.env.PROD && window.pagefind) {
        const response = await window.pagefind.search(keyword);
        searchResults = await Promise.all(
          response.results.map((item) => item.data()),
        );
      } else if (import.meta.env.DEV) {
        searchResults = fakeResult; // 开发环境使用假数据
      }
      result = searchResults;
    } finally {
      isSearching = false;
    }
  }, 300);
};

onMount(() => {
  // 等待 Pagefind 初始化完成
  if (window.pagefind) {
    initialized = true;
  } else {
    document.addEventListener("pagefindready", () => { initialized = true; });
  }
});
</script>

<!-- 桌面端搜索框：favorite 展开 -->
